endpoint.request:
// ADDITIVO ai campi esistenti
"application_scope": "PRODUCT_CATEGORY" | "PRODUCT" | "RECIPIENT",   // esteso
"recipient_id": int | null                                          // nuovo, opzionale
// "recipient_type" NON e' accettato: derivato da recipient_role (D-7)

endpoint.response:
"recipient_type": "referent" | "user" | "registry" | null,          // sola lettura
"recipient_id": int | null,
"recipient": { "id": int, "name": string } | null
// se `recipient_id` non e' visibile, le TRE chiavi sono OMESSE, non messe a null
// (stessa regola gia' applicata a product_id -> product)

endpoint.errors:
422 `recipient_id` mancante con scope RECIPIENT;
422 `product_id`/`product_category_id` valorizzati con scope RECIPIENT;
422 `recipient_id` inesistente nella tabella derivata dal ruolo;
403 senza l'ability `commission-configurations.create`;
422 con l'ability ma senza field permission EDITABILE su `recipient_id` (trait `EnforcesFieldPermissions`).

endpoint.response:
// nuovo descrittore in `data.fields`:
//   { "key": "recipient_id", "type": "select", "group": <stesso di product_id>, "mandatory": false }
// mandatory false: il destinatario e' opzionale a livello di campo; l'obbligo con scope
// RECIPIENT e' una regola cross-field, non una field permission.
// `recipient_type` NON compare: non e' un campo (D-7).
